export type ThreadsAppwriteConfig = {
  endpoint: string
  projectId: string
  databaseId: string
  threadsCollectionId: string
  messagesCollectionId: string
  authorsCollectionId: string
}

export function getThreadsAppwriteConfig(): ThreadsAppwriteConfig {
  return {
    endpoint:
      import.meta.env.VITE_THREADS_APPWRITE_ENDPOINT ??
      'https://fra.cloud.appwrite.io/v1',
    projectId:
      import.meta.env.VITE_THREADS_APPWRITE_PROJECT_ID ?? '656dd556812fe2e5f4ed',
    databaseId: import.meta.env.VITE_THREADS_DB_ID ?? 'main',
    threadsCollectionId:
      import.meta.env.VITE_THREADS_COL_THREADS_ID ?? 'threads',
    messagesCollectionId:
      import.meta.env.VITE_THREADS_COL_MESSAGES_ID ?? 'messages',
    authorsCollectionId:
      import.meta.env.VITE_THREADS_COL_AUTHORS_ID ?? 'authors',
  }
}

export function isThreadsConfigured(): boolean {
  const { endpoint, projectId } = getThreadsAppwriteConfig()
  return Boolean(endpoint && projectId)
}
import { Client, Databases } from '@appwrite.io/console'
import { getThreadsAppwriteConfig } from './config'

let client: Client | null = null
let databases: Databases | null = null

export function getThreadsDatabases(): Databases {
  if (!databases) {
    const config = getThreadsAppwriteConfig()
    client = new Client()
    client.setEndpoint(config.endpoint).setProject(config.projectId)
    databases = new Databases(client)
  }
  return databases
}
export const THREADS_PAGE_SIZE = 25

export const THREADS_DISCORD_GUILD_ID = '564160730845151244'

export const THREADS_DEFAULT_DESCRIPTION =
  'Appwrite is an open-source platform for building applications at any scale, using your preferred programming languages and tools.'

export const THREADS_PRIMARY_TAGS = [
  'Web',
  'Flutter',
  'GraphQL',
  'Cloud',
  'Self Hosted',
] as const

export const THREADS_MORE_TAGS = [
  'Tools',
  'Accounts',
  'Users',
  'Teams',
  'Databases',
  'Storage',
  'Functions',
  'Realtime',
  'Locale',
  'Avatars',
  'Webhooks',
  'General',
  'REST API',
] as const

export const THREADS_ALL_TAGS = [
  ...THREADS_PRIMARY_TAGS,
  ...THREADS_MORE_TAGS,
] as const
import { THREADS_DISCORD_GUILD_ID } from './constants'
import type { ThreadMentionLookup } from './types'

const DISCORD_SNOWFLAKE_PATTERN = /\d{17,20}/
const DISCORD_USER_MENTION_PATTERN = /<@!?(\d{17,20})>/g
const DISCORD_CHANNEL_MENTION_PATTERN = /<#(\d{17,20})>/g

const EMPTY_MENTION_LOOKUP: ThreadMentionLookup = {
  users: {},
  channels: {},
}

/** Discord single-line fenced snippets: ```code``` → `code` for markdown parsers. */
function normalizeDiscordInlineCodeFences(content: string): string {
  return content.replace(/```([^`\n]+?)```/g, '`$1`')
}

function normalizeLineEndings(content: string): string {
  return content.replace(/\r\n/g, '\n')
}

function escapeMarkdownLinkText(text: string): string {
  return text.replace(/[\[\]\\]/g, '\\$&')
}

export function getDiscordChannelUrl(channelId: string): string {
  return `https://discord.com/channels/${THREADS_DISCORD_GUILD_ID}/${channelId}`
}

export function getDiscordUserUrl(userId: string): string {
  return `https://discord.com/users/${userId}`
}

export function getDiscordGuildUrl(): string {
  return `https://discord.com/channels/${THREADS_DISCORD_GUILD_ID}`
}

function getDiscordEmojiUrl(id: string, animated: boolean): string {
  return `https://cdn.discordapp.com/emojis/${id}.${animated ? 'gif' : 'webp'}`
}

function formatDiscordTimestamp(unixSeconds: string): string {
  const date = new Date(Number(unixSeconds) * 1000)
  if (Number.isNaN(date.getTime())) return `<t:${unixSeconds}>`

  return date.toLocaleString(undefined, {
    dateStyle: 'medium',
    timeStyle: 'short',
  })
}

function markdownLink(label: string, href: string): string {
  return `[${escapeMarkdownLinkText(label)}](${href})`
}

function resolveUserMentionLabel(
  userId: string,
  lookup: ThreadMentionLookup,
): string {
  const name = lookup.users[userId]?.trim()
  return name ? `@${name}` : '@user'
}

function resolveChannelMentionLabel(
  channelId: string,
  lookup: ThreadMentionLookup,
): string {
  const channel = lookup.channels[channelId]
  if (channel?.title) return channel.title
  return '#channel'
}

function resolveChannelMentionHref(
  channelId: string,
  lookup: ThreadMentionLookup,
): string {
  return lookup.channels[channelId]?.href ?? getDiscordChannelUrl(channelId)
}

export function extractDiscordMentionIds(contents: string[]): {
  userIds: Set<string>
  channelIds: Set<string>
} {
  const userIds = new Set<string>()
  const channelIds = new Set<string>()

  for (const content of contents) {
    for (const match of content.matchAll(DISCORD_USER_MENTION_PATTERN)) {
      userIds.add(match[1])
    }
    for (const match of content.matchAll(DISCORD_CHANNEL_MENTION_PATTERN)) {
      channelIds.add(match[1])
    }
  }

  return { userIds, channelIds }
}

function replaceDiscordRoleMentions(content: string): string {
  return content.replace(/<@&(\d{17,20})>/g, (_, roleId) => {
    if (!DISCORD_SNOWFLAKE_PATTERN.test(roleId)) return `<@&${roleId}>`
    return markdownLink('@role', getDiscordGuildUrl())
  })
}

function replaceDiscordUserMentions(
  content: string,
  lookup: ThreadMentionLookup,
): string {
  return content.replace(DISCORD_USER_MENTION_PATTERN, (_, userId) => {
    if (!DISCORD_SNOWFLAKE_PATTERN.test(userId)) return `<@${userId}>`
    return markdownLink(
      resolveUserMentionLabel(userId, lookup),
      `/threads/authors/${userId}`,
    )
  })
}

function replaceDiscordChannelMentions(
  content: string,
  lookup: ThreadMentionLookup,
): string {
  return content.replace(DISCORD_CHANNEL_MENTION_PATTERN, (_, channelId) => {
    if (!DISCORD_SNOWFLAKE_PATTERN.test(channelId)) return `<#${channelId}>`
    return markdownLink(
      resolveChannelMentionLabel(channelId, lookup),
      resolveChannelMentionHref(channelId, lookup),
    )
  })
}

function replaceDiscordCustomEmojis(content: string): string {
  return content
    .replace(/<a:(\w+):(\d{17,20})>/g, (_, name, id) => {
      return `![${name}](${getDiscordEmojiUrl(id, true)})`
    })
    .replace(/<:(\w+):(\d{17,20})>/g, (_, name, id) => {
      return `![${name}](${getDiscordEmojiUrl(id, false)})`
    })
}

function replaceDiscordTimestamps(content: string): string {
  return content.replace(/<t:(\d{10,13})(?::[a-zA-Z])?>/g, (_, unix) => {
    const normalizedUnix =
      unix.length > 10 ? String(Math.floor(Number(unix) / 1000)) : unix
    return formatDiscordTimestamp(normalizedUnix)
  })
}

function replaceDiscordSlashCommands(content: string): string {
  return content.replace(/<\/([^:>\n]+):(\d{17,20})>/g, (_, name) => {
    return `\`/${String(name).trim()}\``
  })
}

function replaceDiscordSpoilers(content: string): string {
  return content.replace(/\|\|([^|\n]+?)\|\|/g, (_, text: string) => text)
}

function replaceDiscordMentionsForMarkdown(
  content: string,
  lookup: ThreadMentionLookup,
): string {
  let result = content
  result = replaceDiscordRoleMentions(result)
  result = replaceDiscordUserMentions(result, lookup)
  result = replaceDiscordChannelMentions(result, lookup)
  result = replaceDiscordCustomEmojis(result)
  result = replaceDiscordTimestamps(result)
  result = replaceDiscordSlashCommands(result)
  result = replaceDiscordSpoilers(result)
  return result
}

function replaceDiscordMentionsForPlainText(
  content: string,
  lookup: ThreadMentionLookup,
): string {
  let result = content
  result = result.replace(/<@&(\d{17,20})>/g, '@role')
  result = result.replace(DISCORD_USER_MENTION_PATTERN, (_, userId) =>
    resolveUserMentionLabel(userId, lookup),
  )
  result = result.replace(DISCORD_CHANNEL_MENTION_PATTERN, (_, channelId) =>
    resolveChannelMentionLabel(channelId, lookup),
  )
  result = result.replace(/<a?:(\w+):\d{17,20}>/g, ':$1:')
  result = result.replace(/<t:(\d{10,13})(?::[a-zA-Z])?>/g, (_, unix) => {
    const normalizedUnix =
      unix.length > 10 ? String(Math.floor(Number(unix) / 1000)) : unix
    return formatDiscordTimestamp(normalizedUnix)
  })
  result = result.replace(/<\/([^:>\n]+):\d{17,20}>/g, '/$1')
  result = replaceDiscordSpoilers(result)
  return result
}

export function prepareThreadMessageForMarkdown(
  content: string,
  mentionLookup: ThreadMentionLookup = EMPTY_MENTION_LOOKUP,
): string {
  let result = normalizeLineEndings(content)
  result = replaceDiscordMentionsForMarkdown(result, mentionLookup)
  result = normalizeDiscordInlineCodeFences(result)
  return result
}

export function normalizeThreadPlainText(
  content: string,
  mentionLookup: ThreadMentionLookup = EMPTY_MENTION_LOOKUP,
): string {
  let result = normalizeLineEndings(content)
  result = replaceDiscordMentionsForPlainText(result, mentionLookup)
  result = normalizeDiscordInlineCodeFences(result)
  return result
}

export function isDiscordEmojiImageUrl(src?: string): boolean {
  return Boolean(src?.includes('cdn.discordapp.com/emojis/'))
}
import { Query } from '@appwrite.io/console'
import { getThreadsAppwriteConfig, isThreadsConfigured } from './config'
import { getThreadsDatabases } from './client'
import { extractDiscordMentionIds, normalizeThreadPlainText } from './markdown'
import { THREADS_DISCORD_GUILD_ID, THREADS_PAGE_SIZE } from './constants'
import type {
  DiscordAuthor,
  DiscordMessage,
  DiscordThread,
  ThreadMentionLookup,
  ThreadsListResult,
} from './types'

type Ranked<T> = {
  data: T
  rank: number
}

type FilterThreadsArgs = {
  threads: DiscordThread[]
  q?: string | null
  tags?: string[]
  allTags?: boolean
}

export function sanitizeThreadContent(
  rawContent: string,
  maxLength: number = 200,
  mentionLookup?: ThreadMentionLookup,
): string {
  const cleaned = normalizeThreadPlainText(rawContent, mentionLookup).replace(
    /```(?:\w+)?\n([\s\S]*?)```|```([\s\S]*?)```/g,
    (_, withLang, withoutLang) => (withLang || withoutLang).trim(),
  )

  return cleaned.length > maxLength
    ? `${cleaned.slice(0, maxLength)}...`
    : cleaned
}

export function filterThreads({
  q,
  threads: threadDocs,
  tags,
  allTags,
}: FilterThreadsArgs): DiscordThread[] {
  const threads = tags?.length
    ? threadDocs.filter((thread) => {
        const threadTags = thread.tags ?? []
        if (allTags) {
          return tags.every((tag) => threadTags.includes(tag))
        }
        return tags.some((tag) => threadTags.includes(tag))
      })
    : threadDocs

  if (!q) return threads

  const queryWords = q.toLowerCase().split(/\s+/).filter(Boolean)
  const rankPerWord = 1 / queryWords.length
  const res: Ranked<DiscordThread>[] = []

  threads.forEach((item) => {
    const foundWords = new Set<string>()

    Object.values(item).forEach((value) => {
      const stringified = JSON.stringify(value).toLowerCase()

      queryWords.forEach((word) => {
        if (stringified.includes(word)) {
          foundWords.add(word)
        }
      })
    })

    const rank = foundWords.size * rankPerWord

    if (rank > 0) {
      res.push({ data: item, rank })
    }
  })

  return res.sort((a, b) => b.rank - a.rank).map(({ data }) => data)
}

type GetThreadsArgs = {
  q?: string | null
  tags?: string[]
  allTags?: boolean
  cursor?: string
}

export async function getThreads({
  q,
  tags,
  allTags,
  cursor,
}: GetThreadsArgs): Promise<ThreadsListResult> {
  const config = getThreadsAppwriteConfig()
  const databases = getThreadsDatabases()

  const normalizedTags = tags?.filter(Boolean) ?? []

  let query = [
    q ? Query.search('search_meta', q) : undefined,
    Query.orderDesc('$createdAt'),
    Query.limit(THREADS_PAGE_SIZE),
    cursor ? Query.cursorAfter(cursor) : undefined,
    normalizedTags.length > 0 ? Query.contains('tags', normalizedTags) : undefined,
  ].filter(Boolean) as string[]

  const data = await databases.listDocuments(
    config.databaseId,
    config.threadsCollectionId,
    query,
  )

  const threadDocs = data.documents as unknown as DiscordThread[]
  const filtered = filterThreads({
    threads: threadDocs,
    q,
    tags: normalizedTags,
    allTags,
  })
  const hasMore = data.documents.length === THREADS_PAGE_SIZE
  const nextCursor = hasMore
    ? data.documents[data.documents.length - 1]?.$id
    : undefined

  return {
    threads: filtered,
    hasMore,
    nextCursor,
    total: data.total,
  }
}

export async function getAuthor(discordId: string): Promise<DiscordAuthor> {
  const config = getThreadsAppwriteConfig()
  const databases = getThreadsDatabases()

  return (await databases.getDocument(
    config.databaseId,
    config.authorsCollectionId,
    discordId,
  )) as unknown as DiscordAuthor
}

export async function getAuthorThreads(authorId: string) {
  const config = getThreadsAppwriteConfig()
  const databases = getThreadsDatabases()

  const data = await databases.listDocuments(
    config.databaseId,
    config.threadsCollectionId,
    [
      Query.equal('author_id', authorId),
      Query.orderDesc('$createdAt'),
      Query.limit(THREADS_PAGE_SIZE),
    ],
  )

  return {
    threads: data.documents as unknown as DiscordThread[],
    total: data.total,
  }
}

export async function getThread(threadId: string): Promise<DiscordThread> {
  const config = getThreadsAppwriteConfig()
  const databases = getThreadsDatabases()

  return (await databases.getDocument(
    config.databaseId,
    config.threadsCollectionId,
    threadId,
  )) as unknown as DiscordThread
}

function seedMentionLookupFromMessages(
  messages: DiscordMessage[],
): ThreadMentionLookup {
  const users: Record<string, string> = {}

  for (const message of messages) {
    if (message.author_id && message.author) {
      users[message.author_id] = message.author
    }
  }

  return { users, channels: {} }
}

export async function resolveThreadMentionLookup(
  contents: string[],
  messages: DiscordMessage[] = [],
): Promise<ThreadMentionLookup> {
  const lookup = seedMentionLookupFromMessages(messages)
  const { userIds, channelIds } = extractDiscordMentionIds(contents)

  const missingAuthorIds = [...userIds].filter((id) => !lookup.users[id])
  await Promise.all(
    missingAuthorIds.map(async (authorId) => {
      try {
        const author = await getAuthor(authorId)
        lookup.users[authorId] = author.display_name || author.username
      } catch {
        // Author may not exist in the synced authors collection.
      }
    }),
  )

  await Promise.all(
    [...channelIds].map(async (channelId) => {
      if (lookup.channels[channelId]) return

      try {
        const thread = await getThread(channelId)
        lookup.channels[channelId] = {
          title: thread.title,
          href: getThreadHref(thread),
        }
      } catch {
        // Channel id is a Discord channel, not a mirrored forum thread.
      }
    }),
  )

  return lookup
}

export async function getThreadMessages(
  threadId: string,
): Promise<DiscordMessage[]> {
  const config = getThreadsAppwriteConfig()
  const databases = getThreadsDatabases()

  const data = await databases.listDocuments(
    config.databaseId,
    config.messagesCollectionId,
    [Query.equal('threadId', threadId)],
  )

  return (data.documents as unknown as DiscordMessage[]).sort(
    (a, b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime(),
  )
}

export async function getRelatedThreads(
  thread: DiscordThread,
  limit: number = 3,
): Promise<DiscordThread[]> {
  const tags = thread.tags?.filter(Boolean) ?? []
  const { threads } = await getThreads({ tags, allTags: false })
  return threads.filter(({ $id }) => $id !== thread.$id).slice(0, limit)
}

export async function* iterateAllThreads(total?: number) {
  if (!isThreadsConfigured()) return

  const config = getThreadsAppwriteConfig()
  const databases = getThreadsDatabases()
  const limit = 100
  let cursor: string | undefined
  let count = 0

  while (true) {
    const queries = [Query.limit(limit), Query.orderAsc('$id')]
    if (cursor) {
      queries.push(Query.cursorAfter(cursor))
    }

    const data = await databases.listDocuments(
      config.databaseId,
      config.threadsCollectionId,
      queries,
    )

    if (data.documents.length === 0) break

    for (const thread of data.documents as unknown as DiscordThread[]) {
      yield thread
      count++
      if (total !== undefined && count >= total) return
    }

    if (data.documents.length < limit) break

    cursor = data.documents[data.documents.length - 1]?.$id
  }
}

/** Public thread URL segment (matches in-app links and canonical URLs). */
export function getThreadPublicId(
  thread: Pick<DiscordThread, '$id' | 'discord_id'>,
): string {
  const discordId = thread.discord_id?.trim()
  return discordId || thread.$id
}

export async function getAllThreadIds(): Promise<string[]> {
  const ids: string[] = []
  for await (const thread of iterateAllThreads()) {
    ids.push(getThreadPublicId(thread))
  }
  return ids
}

export function getDiscordThreadUrl(discordId: string): string {
  return `https://discord.com/channels/${THREADS_DISCORD_GUILD_ID}/${discordId}`
}

export function isThreadResolved(thread: DiscordThread): boolean {
  return (
    Boolean(thread.is_resolved) ||
    /\[(solved|resolved|closed|fixed)\]/i.test(thread.title)
  )
}

export function getThreadHref(thread: DiscordThread): string {
  return `/threads/${getThreadPublicId(thread)}`
}

export function getAuthorHref(authorId: string): string {
  return `/threads/authors/${authorId}`
}

export function formatThreadsTotal(total: number): string {
  if (total >= 1000) {
    return `${Math.floor(total / 1000)}000+`
  }
  return String(total)
}

export function getAuthorDescription(author: DiscordAuthor): string {
  return (
    author.bio ??
    `${author.display_name} has posted ${author.thread_count} threads and ${author.reply_count} replies on the Appwrite Discord community.`
  )
}

export function cleanThreadRoleLabel(role: string | undefined): string {
  if (!role) return ''

  return role
    .replace(/<a?:[^:>\s]+:\d+>/g, '')
    .replace(/[\p{Extended_Pictographic}\p{Emoji_Presentation}\uFE0F\u200D]/gu, '')
    .replace(/\s+/g, ' ')
    .trim()
}
import { MARKETING_SITE_ORIGIN } from '@/lib/marketing/urls'
import { getSeoSiteOrigin } from '@/lib/marketing/site-origin'
import { buildOgImageUrl, OG_IMAGE_HEIGHT, OG_IMAGE_WIDTH } from '@/lib/seo/og-image'
import {
  DISCORD_EMBED_ACCENT_COLOR,
  escapeDiscordMarkdown,
  getDiscordLinkButton,
  getDiscordTimestamp,
  truncateDiscordText,
  type DiscordContainer,
  type DiscordTextDisplay,
} from '@/lib/seo/discord-embed'
import { sanitizeJsonLdText } from '@/lib/seo/json-ld'
import type { DiscordAuthor, DiscordMessage, DiscordThread } from './types'
import {
  getAuthorDescription,
  getDiscordThreadUrl,
  isThreadResolved,
  sanitizeThreadContent,
} from './content'
import { THREADS_DEFAULT_DESCRIPTION } from './constants'

const THREAD_META_DESCRIPTION_MAX_LENGTH = 160

export function isSeoKeywordListDescription(text: string): boolean {
  const trimmed = text.trim()
  if (!trimmed || !trimmed.includes(',')) return false
  if (/[.!?]/.test(trimmed)) return false

  const segments = trimmed
    .split(',')
    .map((segment) => segment.trim())
    .filter(Boolean)
  if (segments.length < 3) return false

  const keywordLike = segments.filter(
    (segment) => segment.length <= 48 && segment.split(/\s+/).length <= 6,
  )
  return keywordLike.length >= Math.ceil(segments.length * 0.75)
}

function truncateThreadMetaDescription(text: string): string {
  const cleaned = text.replace(/\s+/g, ' ').trim()
  if (cleaned.length <= THREAD_META_DESCRIPTION_MAX_LENGTH) return cleaned

  const sliced = cleaned.slice(0, THREAD_META_DESCRIPTION_MAX_LENGTH - 3)
  const lastSpace = sliced.lastIndexOf(' ')
  if (lastSpace > THREAD_META_DESCRIPTION_MAX_LENGTH * 0.55) {
    return `${sliced.slice(0, lastSpace)}...`
  }
  return `${sliced}...`
}

export function getThreadMetaDescription(
  thread: Pick<
    DiscordThread,
    'title' | 'seo_description' | 'tldr' | 'content'
  >,
): string {
  const title = thread.title.trim()
  const seoDescription = thread.seo_description?.trim()
  if (
    seoDescription &&
    seoDescription !== title &&
    !isSeoKeywordListDescription(seoDescription)
  ) {
    return truncateThreadMetaDescription(seoDescription)
  }

  const tldr = thread.tldr?.trim()
  if (tldr) {
    return truncateThreadMetaDescription(
      sanitizeThreadContent(tldr, THREAD_META_DESCRIPTION_MAX_LENGTH),
    )
  }

  const content = thread.content?.trim()
  if (content) {
    return truncateThreadMetaDescription(
      sanitizeThreadContent(content, THREAD_META_DESCRIPTION_MAX_LENGTH),
    )
  }

  return THREADS_DEFAULT_DESCRIPTION
}

function getThreadsDefaultOgImage(siteOrigin?: string): string {
  return buildOgImageUrl(
    {
      title: 'Appwrite Threads',
      eyebrow: 'Threads',
      subtitle: THREADS_DEFAULT_DESCRIPTION,
    },
    siteOrigin,
  )
}

export function getThreadsCanonicalUrl(path: string): string {
  return `${MARKETING_SITE_ORIGIN}${path}`
}

export function getThreadsPageTitle(title: string): string {
  return `${title} · Appwrite`
}

export function getThreadOgImageUrl(
  thread: Pick<
    DiscordThread,
    'title' | 'seo_description' | 'tldr' | 'content'
  >,
  siteOrigin?: string,
): string {
  const title = thread.title.trim()
  const subtitle = getThreadMetaDescription(thread)

  return buildOgImageUrl(
    {
      title,
      eyebrow: 'Threads',
      subtitle,
    },
    siteOrigin,
  )
}

export function getThreadsIndexMetaTags(siteOrigin?: string) {
  const title = getThreadsPageTitle('Threads')
  const description =
    "Appwrite's Threads page showcases our community interactions on Discord. Join the conversation, ask questions, or assist other members with their issues."
  const canonical = getThreadsCanonicalUrl('/threads')
  const resolvedOrigin = getSeoSiteOrigin(siteOrigin)
  const ogImage = getThreadsDefaultOgImage(resolvedOrigin)

  return [
    { title },
    { name: 'description', content: description },
    { property: 'og:title', content: title },
    { property: 'og:description', content: description },
    { property: 'og:type', content: 'website' },
    { property: 'og:url', content: canonical },
    { property: 'og:image', content: ogImage },
    { property: 'og:image:width', content: String(OG_IMAGE_WIDTH) },
    { property: 'og:image:height', content: String(OG_IMAGE_HEIGHT) },
    { name: 'twitter:card', content: 'summary_large_image' },
    { name: 'twitter:title', content: title },
    { name: 'twitter:description', content: description },
    { name: 'twitter:image', content: ogImage },
  ] as const
}

export function getThreadsThreadMetaTags(
  thread: DiscordThread,
  canonicalUrl: string,
  siteOrigin?: string,
) {
  const pageTitle = getThreadsPageTitle(`${thread.title} - Threads`)
  const description = getThreadMetaDescription(thread)
  const resolvedOrigin = getSeoSiteOrigin(siteOrigin)
  const ogImage = getThreadOgImageUrl(thread, resolvedOrigin)

  return [
    { title: pageTitle },
    { name: 'description', content: description },
    { property: 'og:title', content: pageTitle },
    { property: 'og:description', content: description },
    { property: 'og:type', content: 'article' },
    { property: 'og:url', content: canonicalUrl },
    { property: 'og:image', content: ogImage },
    { property: 'og:image:width', content: String(OG_IMAGE_WIDTH) },
